//! 📦️ The selected schema frame stays resident through its paid page reservation and placement.
use super::*;
use semio_framework_value_native_decoding::native_decoding::{OriginalEffectReply,OriginalEffectReplyComplete};
use semio_framework_value_persistent::list::{PagedListReservationFailure,PagedListReservationOutcome};

impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 📐️ Quotes the selected native reservation or resident-frame placement and outer reply.
 pub fn pending_slot_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.pending.is_none(){return Err(invalid())}let mut demand=if self.frames.has_reserved_slot(){self.frames.adoption_demand(&self.pending)?}else{RetirementDemand{copy_bytes:page(self.frames.next_reserve_copy_byte_demand())?,capacity_bytes:page(self.frames.next_allocation_bytes())?,depth:page(self.frames.next_reserve_depth_demand())?.max(1),..Default::default()}};demand.copy_bytes=demand.copy_bytes.checked_add(size_of::<Option<Result<RetainedCloneStep,ValueError>>>()).ok_or_else(invalid)?;Ok(demand)}
 /// ⏱️ Quotes the actual selected page operation and native outer reply.
 pub fn pending_slot_work_demand(&self)->Result<u64,ValueError>{self.pending_slot_demand()?;let work=if self.frames.has_reserved_slot(){1}else{page(self.frames.reserve_one_work_demand())?};work.checked_add(1).ok_or_else(invalid)}
 /// 📥️ Drives only the selected bounded native page leaf on the original effect.
 pub fn pending_slot_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.pending_slot_demand()?;let work=self.pending_slot_work_demand()?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"schema pending reply exceeded Work"))))}let reply_bytes=size_of::<Option<Result<RetainedCloneStep,ValueError>>>();let grant=RetainedCloneGrant{maximum_copy_bytes:effect.grant().maximum_copy_bytes.checked_sub(reply_bytes).ok_or_else(invalid)?,..effect.grant()};let mut child=effect.reborrow(grant,effect.remaining_work_units()?)?;let result=if self.frames.has_reserved_slot(){let turn=self.frames.adopt_reserved(&mut self.pending,&mut child);turn.result.map(|progress|RetainedCloneProgress{copied_items:usize::from(progress.progressed),copied_bytes:progress.placed_bytes,retained_capacity_bytes:progress.allocated_bytes,released_bytes:progress.released_allocation_bytes})}else{let turn=self.frames.reserve_one(&mut child);match turn.result{Ok(PagedListReservationOutcome::Denied)=>Ok(Default::default()),Ok(PagedListReservationOutcome::Ready(progress))=>Ok(RetainedCloneProgress{copied_items:usize::from(progress.progressed),copied_bytes:progress.placed_bytes,retained_capacity_bytes:progress.allocated_bytes,released_bytes:progress.released_allocation_bytes}),Err(PagedListReservationFailure::Work(error))=>Err(error),Err(PagedListReservationFailure::Allocation{error,copied_bytes})=>Err(ValueError::from(error.refusal()).with_retained_progress(RetainedCloneProgress{copied_items:usize::from(copied_bytes!=0||error.allocated_bytes!=0),copied_bytes,retained_capacity_bytes:error.allocated_bytes,..Default::default()}))}};let result=result.and_then(|mut progress|{progress.copied_items=progress.copied_items.max(1);progress.copied_bytes=progress.copied_bytes.checked_add(reply_bytes).ok_or_else(invalid)?;Ok(RetainedCloneStep::Progress(progress))}).map_err(|error|{let mut progress=error.retained_progress();if let Some(bytes)=progress.copied_bytes.checked_add(reply_bytes){progress.copied_items=progress.copied_items.max(1);progress.copied_bytes=bytes;error.with_retained_progress(progress)}else{error}});Ok(reply.complete(result))}
}
